// Validates the central configuration and plans the AI-call budget up front.
// The system never switches AI providers and never exceeds max_ai_calls_per_execution.
const c = $input.first().json;
const errors = [];
const warnings = [];

const runMode = String(c.run_mode || '').toLowerCase().trim();
if (runMode !== 'simulation' && runMode !== 'live') errors.push('run_mode must be "simulation" or "live" (got "' + c.run_mode + '").');
if (String(c.primary_ai || '').toLowerCase() !== 'groq') errors.push('primary_ai must be "groq" for the Groq Chat Completions route. The system will not switch providers silently.');
if (String(c.secondary_ai || '').toLowerCase() !== 'claude') errors.push('secondary_ai must be "claude". No other reviewer is wired and the system will not switch providers silently.');

const maxIdeas = Number(c.max_ideas);
if (!Number.isInteger(maxIdeas) || maxIdeas < 1 || maxIdeas > 5) errors.push('max_ideas must be an integer between 1 and 5.');
const maxCalls = Number(c.max_ai_calls_per_execution);
if (!Number.isInteger(maxCalls) || maxCalls < 0) errors.push('max_ai_calls_per_execution must be a non-negative integer.');
const maxRetries = Number(c.max_retries);
if (maxRetries !== 0) warnings.push('max_retries is ' + c.max_retries + ', but AI nodes have retries disabled; 0 retries will be used.');
const minPrice = Number(c.min_price);
const maxPrice = Number(c.max_price);
if (!(minPrice > 0) || !(maxPrice > 0) || minPrice >= maxPrice) errors.push('min_price and max_price must be positive numbers with min_price < max_price.');
if (String(c.currency || '').toUpperCase() !== 'IDR') errors.push('currency must be "IDR".');
if (c.require_human_approval !== true) errors.push('require_human_approval must stay true. Publishing without owner approval is not allowed.');
if (c.auto_publish !== false) errors.push('auto_publish must stay false. No publishing integration exists yet.');

// AI-call budget plan (deterministic, decided before any call is made)
const live = runMode === 'live';
const plan = { idea_generation: false, product_creation: false, claude_review: false, final_revision: false };
if (live && Number.isInteger(maxCalls)) {
  if (maxCalls < 2) {
    errors.push('Live mode needs at least 2 AI calls (Groq idea generation + Groq product creation); max_ai_calls_per_execution is ' + maxCalls + '.');
  } else {
    plan.idea_generation = true;
    plan.product_creation = true;
  }
  if (c.enable_claude_review === true && plan.product_creation) {
    if (maxCalls >= 3) plan.claude_review = true;
    else warnings.push('Claude review is enabled but will be SKIPPED: it needs a 3rd AI call and max_ai_calls_per_execution is ' + maxCalls + '.');
    if (plan.claude_review) {
      if (maxCalls >= 4) plan.final_revision = true;
      else warnings.push('OpenAI final revision after Claude review will be skipped: it needs a 4th AI call and max_ai_calls_per_execution is ' + maxCalls + '.');
    }
  }
}
const plannedCalls = Object.keys(plan).filter(function (k) { return plan[k]; }).length;

return [{ json: {
  config: {
    run_mode: runMode,
    primary_ai: 'groq',
    secondary_ai: 'claude',
    enable_claude_review: c.enable_claude_review === true,
    max_ideas: maxIdeas,
    max_ai_calls_per_execution: maxCalls,
    max_retries: 0,
    require_human_approval: true,
    auto_publish: false,
    currency: 'IDR',
    min_price: minPrice,
    max_price: maxPrice,
  },
  config_valid: errors.length === 0,
  config_errors: errors,
  config_warnings: warnings,
  ai_plan: plan,
  max_planned_ai_calls: plannedCalls,
  run_started_at: new Date().toISOString(),
} }];

// Collects stored product records. Simulation-mode rows are never treated as real products.
// In simulation mode an explicit, clearly labelled SAMPLE list is added for duplicate testing.
const cfg = $('Validate Configuration').first().json.config;
const rows = [];
let loadError = null;
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error) { loadError = typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)); continue; }
  if (Object.keys(j).length === 0) continue;
  rows.push(j);
}
const liveRows = rows.filter(function (r) { return r.run_mode === 'live' && r.product_status !== 'rejected_qa'; });
let records = liveRows.map(function (r) { return { title: r.product_title || '', product_key: r.product_key || '', status: r.product_status || '', source: 'data_table' }; });

let sampleUsed = false;
if (cfg.run_mode === 'simulation') {
  const samples = [
    'Template Invoice & Pembukuan Sederhana untuk UMKM',
    'Ebook Panduan Jualan di TikTok Shop untuk Pemula',
    'Planner Keuangan Keluarga Bulanan (Google Sheets)',
    'Kumpulan Template Caption Instagram untuk Bisnis Kuliner',
  ];
  records = records.concat(samples.map(function (t) { return { title: t, product_key: '', status: 'sample', source: 'sample' }; }));
  sampleUsed = true;
}

let recordSource;
if (loadError) recordSource = sampleUsed ? 'sample_records_only (data table load failed)' : 'none (data table load failed)';
else if (liveRows.length === 0 && sampleUsed) recordSource = 'sample_records_only';
else if (liveRows.length > 0 && sampleUsed) recordSource = 'data_table_live_records_plus_sample_records';
else recordSource = liveRows.length > 0 ? 'data_table_live_records' : 'data_table_empty';

return [{ json: {
  existing_records: records,
  record_source: recordSource,
  data_table_rows_loaded: rows.length,
  live_records_used: liveRows.length,
  simulation_or_rejected_rows_ignored: rows.length - liveRows.length,
  sample_records_used: sampleUsed,
  load_error: loadError,
} }];

parameters.jsonBody:
={{ ({
  model: "openai/gpt-oss-20b",
  messages: [
    { role: "system", content: "You are a product strategist for LynkFusion, an Indonesian digital-product business. Propose useful digital-product ideas only. Never invent search results, sales figures, demand statistics, testimonials, or guarantees. Respond with valid JSON only." },
    { role: "user", content:
      "Propose exactly " + $('Validate Configuration').first().json.config.max_ideas + " specific digital product ideas for Indonesian customers. Each product must be deliverable as downloadable digital files (templates, workbooks, checklists, guides, spreadsheets) and solve a concrete problem. Write all content in Bahasa Indonesia.\n" +
      "Suggested price per idea must be an integer between " + $('Validate Configuration').first().json.config.min_price + " and " + $('Validate Configuration').first().json.config.max_price + " IDR.\n" +
      "Do not propose ideas that duplicate or closely resemble these existing products: " + ($('Prepare Existing Records').first().json.existing_records.map(r => r.title).join('; ') || 'none') + ".\n" +
      "Return a JSON object with an ideas array. Each idea must have these keys: title, target_audience, customer_problem, proposed_solution, differentiation, suggested_price_idr (integer), and rationale. The rationale must explain reasoning only, without invented statistics or claims of validated demand."
    }
  ],
  response_format: { type: "json_object" },
  reasoning_effort: "low",
  max_completion_tokens: 1800,
  stream: false
}) }}

parameters.jsCode:
// Parses the Groq Chat Completions result without making another API call.
const cfg = $('Validate Configuration').first().json.config;
const j = $input.first().json || {};
function errMsg(e) {
  if (!e) return 'unknown API error';
  if (typeof e === 'string') return e;
  if (e.message) return e.message;
  if (e.error && e.error.message) return e.error.message;
  try { return JSON.stringify(e); } catch (_) { return String(e); }
}
function apiError(r) {
  if (r.errorMessage) return String(r.errorMessage) + (r.errorDescription ? ': ' + r.errorDescription : '');
  if (r.error) return errMsg(r.error);
  if (Number(r.statusCode || r.status) >= 400) return 'HTTP ' + (r.statusCode || r.status) + ': ' + errMsg(r);
  // n8n may wrap a failed HTTP Request as a root-level NodeApiError item.
  if (!Array.isArray(r.choices) && typeof r.message === 'string' && (r.name || r.description || r.context || r.cause)) {
    return String(r.name || 'Request error') + ': ' + r.message + (r.description ? ' — ' + r.description : '');
  }
  return null;
}
function extractText(r) {
  if (typeof r.output_text === 'string') return r.output_text;
  const choices = Array.isArray(r.choices) ? r.choices : (r.data && Array.isArray(r.data.choices) ? r.data.choices : []);
  if (choices.length && choices[0].message) {
    const c = choices[0].message.content;
    if (typeof c === 'string') return c;
    if (Array.isArray(c)) return c.map(x => typeof x === 'string' ? x : (x.text || x.content || '')).join('\n');
  }
  const out = Array.isArray(r.output) ? r.output : [];
  for (const m of out) {
    if (m && Array.isArray(m.content)) {
      const part = m.content.find(x => x && (x.text !== undefined || x.output_text !== undefined));
      if (part) return String(part.text !== undefined ? part.text : part.output_text);
    }
  }
  return null;
}
function parseJson(text) {
  if (text && typeof text === 'object') return text;
  let s = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(s); } catch (_) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('Model returned no JSON object.');
  return JSON.parse(s.slice(a, b + 1));
}
let ideas = [], status = '', calls = 1;
const errors = [];
const problem = apiError(j);
if (problem) {
  status = 'failed: Groq Chat Completions request: ' + problem;
  errors.push(status);
} else {
  try {
    const text = extractText(j);
    if (text === null) throw new Error('No choices[0].message.content found. Response keys: ' + Object.keys(j).join(', '));
    const parsed = parseJson(text);
    const raw = Array.isArray(parsed.ideas) ? parsed.ideas : [];
    ideas = raw.slice(0, Number(cfg.max_ideas) || 1).map(i => ({
      title: String(i.title || '').trim(),
      target_audience: String(i.target_audience || '').trim(),
      customer_problem: String(i.customer_problem || '').trim(),
      proposed_solution: String(i.proposed_solution || '').trim(),
      differentiation: String(i.differentiation || '').trim(),
      suggested_price_idr: Math.round(Number(String(i.suggested_price_idr || '').replace(/[^0-9]/g, '')) || 0),
      rationale: String(i.rationale || '').trim(),
    })).filter(i => i.title.length > 0);
    status = ideas.length ? 'completed: Groq returned ' + ideas.length + ' idea(s)' : 'failed: Groq returned no usable ideas';
    if (!ideas.length) errors.push('Groq returned no usable ideas in JSON key "ideas".');
  } catch (e) {
    status = 'failed: Groq idea response parsing: ' + errMsg(e);
    errors.push(status);
  }
}
return [{ json: { ideas, idea_source: 'groq', openai_status_ideas: status, ai_calls_ideas: calls, idea_errors: errors } }];

// Normalizes titles and compares each idea with existing records and with earlier ideas in this batch.
// exact normalized match => rejected; token similarity >= 0.6 => close match flagged for review.
const input = $input.first().json;
const existing = $('Prepare Existing Records').first().json;
const STOP = ['untuk', 'dan', 'di', 'ke', 'dari', 'yang', 'dengan', 'the', 'for', 'and', 'of', 'a', 'an', 'lengkap', 'paket', 'kit'];
function norm(t) { return String(t || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g, ' ').replace(/ +/g, ' ').trim(); }
function tokens(t) { return norm(t).split(' ').filter(function (w) { return w && STOP.indexOf(w) === -1; }); }
function similarity(a, b) {
  const A = tokens(a); const B = tokens(b);
  if (A.length === 0 || B.length === 0) return 0;
  const setB = {}; B.forEach(function (w) { setB[w] = true; });
  const setA = {}; A.forEach(function (w) { setA[w] = true; });
  let inter = 0; Object.keys(setA).forEach(function (w) { if (setB[w]) inter++; });
  const union = Object.keys(Object.assign({}, setA, setB)).length;
  return union === 0 ? 0 : inter / union;
}

const records = existing.existing_records || [];
const seen = [];
let rejected = 0;
let flagged = 0;
const annotated = (input.ideas || []).map(function (idea) {
  const n = norm(idea.title);
  let status = 'unique';
  let matchedTitle = null;
  let matchedSource = null;
  let best = 0;
  const pool = records.map(function (r) { return { title: r.title, source: r.source }; }).concat(seen.map(function (t) { return { title: t, source: 'same_batch' }; }));
  for (const r of pool) {
    if (norm(r.title) === n) { status = 'exact_duplicate'; matchedTitle = r.title; matchedSource = r.source; best = 1; break; }
    const s = similarity(idea.title, r.title);
    if (s > best) { best = s; if (s >= 0.6) { status = 'close_match'; matchedTitle = r.title; matchedSource = r.source; } }
  }
  if (status === 'exact_duplicate') rejected++;
  if (status === 'close_match') flagged++;
  seen.push(idea.title);
  return Object.assign({}, idea, {
    normalized_title: n,
    duplicate_status: status,
    duplicate_similarity: Math.round(best * 100) / 100,
    matched_title: matchedTitle,
    matched_source: matchedSource,
  });
});

return [{ json: {
  ideas: annotated,
  ideas_generated: annotated.length,
  duplicates_rejected: rejected,
  close_matches_flagged: flagged,
  record_source: existing.record_source,
  duplicate_check_note: existing.sample_records_used && existing.live_records_used === 0
    ? 'Only SAMPLE records were available; duplicate detection was not checked against real stored products.'
    : 'Checked against ' + existing.live_records_used + ' stored live product record(s)' + (existing.sample_records_used ? ' plus sample records.' : '.'),
  idea_source: input.idea_source,
  openai_status_ideas: input.openai_status_ideas,
  ai_calls_ideas: input.ai_calls_ideas,
  idea_errors: input.idea_errors || [],
} }];

// Deterministic 0-100 score: five criteria worth 0-20 each, computed only from the idea text.
// usefulness: problem detail (8 + 4), concrete deliverable named (4), solution detail (4)
// audience_clarity: audience given (6), detailed (6), specific segment named (8)
// differentiation: given and detailed (8 + 4), local fit (4), no unsupported superlatives (4)
// feasibility: digital file format (10), reasonable scope (5), no ongoing service or custom software (5)
// commercial_potential: price in range (8), rationale given (4), money/time/career outcome (4), paying audience (4)
// penalty: close match to an existing product -10. Exact duplicates are excluded. Minimum to select: 50.
const input = $input.first().json;
const cfg = $('Validate Configuration').first().json.config;
const MIN_SCORE = 50;
function has(text, words) { const t = String(text || '').toLowerCase(); return words.some(function (w) { return t.indexOf(w) !== -1; }); }
const DELIVERABLE = ['template', 'checklist', 'panduan', 'workbook', 'sop', 'script', 'planner', 'worksheet', 'lembar', 'contoh', 'modul', 'kalkulator', 'spreadsheet', 'tracker', 'ebook'];
const SEGMENT = ['pemula', 'pemilik', 'mahasiswa', 'fresh graduate', 'ibu', 'freelancer', 'umkm', 'admin', 'guru', 'karyawan', 'online shop', 'kreator', 'panitia', 'organisasi', 'reseller', 'pelajar'];
const LOCAL = ['indonesia', 'lokal', 'rupiah', 'shopee', 'tokopedia', 'tiktok shop', 'whatsapp', 'qris', 'kampus'];
const SUPERLATIVE = ['terbaik', 'nomor 1', 'no. 1', 'paling laris', 'terlaris', 'dijamin', 'pasti'];
const FORMAT = ['template', 'ebook', 'checklist', 'notion', 'google sheets', 'spreadsheet', 'pdf', 'workbook', 'canva', 'google docs', 'docs'];
const HEAVY = ['coaching 1-on-1', 'mentoring langsung', 'aplikasi custom', 'software custom', 'jasa', 'kelas live'];
const OUTCOME = ['uang', 'waktu', 'omzet', 'kerja', 'pelanggan', 'penjualan', 'hemat', 'gaji', 'karier', 'pesanan', 'sponsor', 'untung', 'rugi'];
const PAYING = ['pemilik', 'bisnis', 'umkm', 'freelancer', 'online shop', 'profesional', 'karyawan', 'fresh graduate', 'panitia'];

function score(i) {
  const b = { usefulness: 0, audience_clarity: 0, differentiation: 0, feasibility: 0, commercial_potential: 0, close_match_penalty: 0 };
  const prob = i.customer_problem || ''; const sol = i.proposed_solution || ''; const aud = i.target_audience || ''; const diff = i.differentiation || '';
  if (prob.length >= 40) b.usefulness += 8;
  if (prob.length >= 80) b.usefulness += 4;
  if (has(sol, DELIVERABLE)) b.usefulness += 4;
  if (sol.length >= 80) b.usefulness += 4;
  if (aud.length > 0) b.audience_clarity += 6;
  if (aud.length >= 25) b.audience_clarity += 6;
  if (has(aud, SEGMENT)) b.audience_clarity += 8;
  if (diff.length >= 30) b.differentiation += 8;
  if (diff.length >= 80) b.differentiation += 4;
  if (has(diff, LOCAL)) b.differentiation += 4;
  if (!has(diff, SUPERLATIVE)) b.differentiation += 4;
  if (has(sol, FORMAT)) b.feasibility += 10;
  if (sol.length >= 40 && sol.length <= 600) b.feasibility += 5;
  if (!has(sol, HEAVY)) b.feasibility += 5;
  const price = Number(i.suggested_price_idr) || 0;
  if (price >= cfg.min_price && price <= cfg.max_price) b.commercial_potential += 8;
  if ((i.rationale || '').length >= 40) b.commercial_potential += 4;
  if (has(prob + ' ' + sol, OUTCOME)) b.commercial_potential += 4;
  if (has(aud, PAYING)) b.commercial_potential += 4;
  if (i.duplicate_status === 'close_match') b.close_match_penalty = -10;
  const total = Math.max(0, Math.min(100, b.usefulness + b.audience_clarity + b.differentiation + b.feasibility + b.commercial_potential + b.close_match_penalty));
  return { total: total, breakdown: b };
}

const ranked = (input.ideas || []).map(function (i, idx) {
  const s = score(i);
  return Object.assign({}, i, { score: s.total, score_breakdown: s.breakdown, eligible: i.duplicate_status !== 'exact_duplicate' && s.total >= MIN_SCORE, original_index: idx });
}).sort(function (a, b) { return b.score - a.score || a.original_index - b.original_index; });

const selected = ranked.find(function (i) { return i.eligible; }) || null;
const errors = (input.idea_errors || []).slice();
if (!selected) errors.push(ranked.length === 0 ? 'No ideas were available to score.' : 'No idea passed duplicate checks with a score of at least ' + MIN_SCORE + '.');

return [{ json: Object.assign({}, input, {
  scoring_method: 'Deterministic rule-based score (0-100): usefulness, audience_clarity, differentiation, feasibility, commercial_potential at 0-20 each, minus 10 for close matches. Exact duplicates excluded; minimum ' + MIN_SCORE + ' to be selected. The AI does not set the score.',
  ranked_ideas: ranked.map(function (i) { return { title: i.title, score: i.score, score_breakdown: i.score_breakdown, duplicate_status: i.duplicate_status, eligible: i.eligible }; }),
  has_valid_candidate: selected !== null,
  selected_idea: selected,
  selected_score: selected ? selected.score : null,
  selected_score_breakdown: selected ? selected.score_breakdown : null,
  idea_errors: errors,
}) }];

