  }
  const out = Array.isArray(r.output) ? r.output : [];
  for (const m of out) {
    if (m && Array.isArray(m.content)) {
      const part = m.content.find(x => x && (x.text !== undefined || x.output_text !== undefined));
      if (part) return String(part.text !== undefined ? part.text : part.output_text);
    }
  }
