Reply with ONLY a JSON object of the form {"verdict":"approve|revise|reject","risk_level":"low|medium|high","issues":[{"category":"","description":"","severity":"low|medium|high"}],"improvements":[""],"unsupported_claims":[""],"missing_sections":[""],"pricing_assessment":""}.

