// Parses Claude's structured review. If the node is disabled or the credential is missing, says so plainly.
const j = $input.first().json || {};
const draft = $('Parse Product Draft').first().json;
const plan = $('Validate Configuration').first().json.ai_plan;
function errMsg(e) { if (!e) return 'unknown error'; if (typeof e === 'string') return e; return e.message || JSON.stringify(e); }
let review = null;
let status;
let calls = 0;
const errors = [];
let text = null;
if (typeof j.merged_response === 'string') text = j.merged_response;
else if (Array.isArray(j.content)) { const blk = j.content.find(function (c) { return c && c.type === 'text'; }); text = blk ? blk.text : null; }
if (j.error) {
  calls = 1;
  status = 'failed: ' + errMsg(j.error);
  errors.push('Claude review failed: ' + errMsg(j.error));
} else if (text === null) {
  status = 'not_configured: "Claude Independent Review" is disabled or has no Anthropic credential. The review did NOT happen.';
  errors.push(status);
} else {
  calls = 1;
  try {
    const a = text.indexOf('{'); const b = text.lastIndexOf('}');
    if (a === -1 || b <= a) throw new Error('response was not JSON');
    const r = JSON.parse(text.slice(a, b + 1));
    const verdicts = ['approve', 'revise', 'reject'];
    const risks = ['low', 'medium', 'high'];
    if (verdicts.indexOf(r.verdict) === -1 || risks.indexOf(r.risk_level) === -1 || !Array.isArray(r.issues) || !Array.isArray(r.improvements)) throw new Error('structured output is missing verdict, risk_level, issues, or improvements');
    review = r;
    status = 'completed: verdict=' + r.verdict + ', risk=' + r.risk_level;
  } catch (e) {
    status = 'failed: ' + errMsg(e);
    errors.push('Could not parse Claude review: ' + errMsg(e));
  }
}
return [{ json: Object.assign({}, draft, {
  review: review,
  claude_status: status,
  ai_calls_review: calls,
  review_errors: errors,
  review_needs_revision: !!(review && review.verdict === 'revise' && review.improvements.length > 0),
  final_revision_allowed: plan.final_revision === true,
}) }];

