// Uses the revised draft if it parsed; otherwise keeps the reviewed draft and reports why.
const j = $input.first().json || {};
const prev = $('Parse Claude Review').first().json;
function errMsg(e) { if (!e) return 'unknown error'; if (typeof e === 'string') return e; return e.message || JSON.stringify(e); }
let product = prev.product;
let status;
let calls = 0;
const errors = (prev.product_errors || []).slice();
if (j.error) { calls = 1; status = 'failed: ' + errMsg(j.error) + ' (kept pre-revision draft)'; errors.push('OpenAI final revision failed: ' + errMsg(j.error)); }
else if (j.output === undefined) { status = 'not_configured: "OpenAI Final Revision" is disabled or has no credential (kept pre-revision draft)'; errors.push(status); }
else {
  calls = 1;
  try {
    let content = null;
    for (const m of (Array.isArray(j.output) ? j.output : [])) {
      if (m && Array.isArray(m.content)) { for (const p of m.content) { if (p && p.text !== undefined && p.text !== null) { content = p.text; break; } } }
      if (content !== null) break;
    }
    if (content === null) throw new Error('no text content');
    let revised = content;
    if (typeof revised !== 'object') { const s = String(revised); const a = s.indexOf('{'); const b = s.lastIndexOf('}'); revised = JSON.parse(s.slice(a, b + 1)); }
    revised.suggested_price_idr = Math.round(Number(String(revised.suggested_price_idr || '').replace(/[^0-9]/g, '')) || 0);
    revised.draft_label = 'DRAFT (AI generated, revised after Claude review) - not approved, not published';
    product = revised;
    status = 'completed: revised draft applied';
  } catch (e) { status = 'failed: ' + errMsg(e) + ' (kept pre-revision draft)'; errors.push('Could not parse revised draft: ' + errMsg(e)); }
}
return [{ json: Object.assign({}, prev, { product: product, revision_status: status, ai_calls_revision: calls, product_errors: errors }) }];

// Validates required fields, completeness, price range, duplicate status, review status, and claims.
// A passing QA only means the draft is complete enough for owner review. It is NOT evidence of demand or sales.
const d = $input.first().json;
const v = $('Validate Configuration').first().json;
const cfg = v.config;
const plan = v.ai_plan;
const sel = $('Score & Select Idea').first().json;
const existing = $('Prepare Existing Records').first().json.existing_records || [];
const p = d.product || null;
const failures = [];
const warnings = [];
function norm(t) { return String(t || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g, ' ').replace(/ +/g, ' ').trim(); }
function str(x) { return typeof x === 'string' ? x.trim() : ''; }

if (!p) {
  failures.push('No product draft is available (' + (d.openai_status_product || 'unknown reason') + ').');
} else {
  if (!str(p.title)) failures.push('Missing title.');
  if (str(p.description).length < 150) failures.push('Description is missing or shorter than 150 characters.');
  if (!str(p.target_audience)) failures.push('Missing target audience.');
  if (!Array.isArray(p.customer_benefits) || p.customer_benefits.filter(str).length < 3) failures.push('Fewer than 3 customer benefits.');
  if (!Array.isArray(p.deliverables) || p.deliverables.filter(function (x) { return x && str(x.name) && str(x.format) && str(x.details); }).length < 2) failures.push('Fewer than 2 fully described deliverables (name, format, details).');
  const sections = Array.isArray(p.outline) ? p.outline.filter(function (s) { return s && str(s.section) && Array.isArray(s.contents) && s.contents.filter(str).length >= 2; }) : [];
  if (sections.length < 4) failures.push('Outline has fewer than 4 sections with at least 2 concrete content items each (empty outline).');
  const sc = p.sales_copy || {};
  if (!str(sc.headline)) failures.push('Sales copy headline missing.');
  if (str(sc.body).length < 150) failures.push('Sales copy body missing or shorter than 150 characters.');
  if (!str(sc.call_to_action)) failures.push('Sales copy call to action missing.');
  if (!str(p.pricing_rationale)) failures.push('Pricing rationale missing.');
  if (cfg.run_mode === 'live') {
    const pc = p.product_content || {};
    const chapters = Array.isArray(pc.chapters) ? pc.chapters.filter(function (x) { return x && str(x.title) && str(x.content).length >= 400; }) : [];
    const templates = Array.isArray(pc.templates) ? pc.templates.filter(function (x) { return x && str(x.name) && str(x.content).length >= 100; }) : [];
    if (str(pc.introduction).length < 100) failures.push('Buyer-ready product introduction is missing or too short.');
    if (chapters.length < 4) failures.push('Product content needs at least 4 fully written chapters (each at least 400 characters).');
    if (templates.length < 2) failures.push('Product content needs at least 2 complete templates/worksheets (each at least 100 characters).');
    if (str(pc.usage_instructions).length < 100) failures.push('Product usage instructions are missing or too short.');
  }
  const price = Number(p.suggested_price_idr);
  if (!Number.isInteger(price) || price < cfg.min_price || price > cfg.max_price) failures.push('Price ' + p.suggested_price_idr + ' is outside ' + cfg.min_price + '-' + cfg.max_price + ' IDR.');

  // Duplicate checks: selected idea and final product title
  if (sel.selected_idea && sel.selected_idea.duplicate_status === 'exact_duplicate') failures.push('Selected idea is an exact duplicate of an existing product.');
  if (sel.selected_idea && sel.selected_idea.duplicate_status === 'close_match') warnings.push('Selected idea closely matches "' + sel.selected_idea.matched_title + '" (' + sel.selected_idea.matched_source + '). Owner should confirm it is distinct.');
  const pt = norm(p.title);
  const dupTitle = existing.find(function (r) { return norm(r.title) === pt; });
  if (dupTitle) failures.push('Final product title duplicates existing product "' + dupTitle.title + '" (' + dupTitle.source + ').');

  // Exaggerated / unsupported claims
  const text = JSON.stringify(p).toLowerCase();
  const HARD = ['dijamin', 'garansi hasil', 'pasti laku', 'pasti untung', 'pasti diterima', 'pasti berhasil', '100%', 'guaranteed', 'terbukti', 'ribuan pembeli', 'ribuan pelanggan', 'terlaris', 'best seller', 'bestseller', 'nomor 1', 'no. 1', 'cepat kaya', 'kaya mendadak'];
  const SOFT = ['passive income', 'omzet naik', 'tanpa modal', 'auto cuan', 'laris manis'];
  HARD.forEach(function (w) { if (text.indexOf(w) !== -1) failures.push('Unsupported or exaggerated claim found: "' + w + '". Remove it or provide evidence.'); });
  SOFT.forEach(function (w) { if (text.indexOf(w) !== -1) warnings.push('Potentially exaggerated phrase: "' + w + '". Review before publishing.'); });
}

// Review status
let claudeStatus = d.claude_status;
if (!claudeStatus) {
  if (cfg.run_mode !== 'live') claudeStatus = 'not_run: simulation mode (no API call)';
  else if (!cfg.enable_claude_review) claudeStatus = 'disabled: enable_claude_review is false';
  else if (!plan.claude_review) claudeStatus = 'skipped: AI-call budget (max_ai_calls_per_execution=' + cfg.max_ai_calls_per_execution + ') does not allow a 3rd call';
  else if (!d.product_ok) claudeStatus = 'skipped: no product draft to review';
  else claudeStatus = 'not_run';
}
if (d.review) {
  if (d.review.verdict === 'reject') failures.push('Claude review verdict is "reject".');
  if (d.review.risk_level === 'high') failures.push('Claude review risk level is "high".');
  if (d.review.verdict === 'revise' && !String(d.revision_status || '').startsWith('completed')) warnings.push('Claude requested revisions that were not applied automatically: ' + (d.review.improvements || []).join(' | '));
}
if (cfg.run_mode === 'live' && cfg.enable_claude_review && !String(claudeStatus).startsWith('completed')) warnings.push('Claude review was requested but did not complete: ' + claudeStatus);
if (cfg.run_mode === 'simulation') warnings.push('Simulation mode: content is sample data and was not produced or reviewed by any AI.');

const ideaStatusNode = $('Score & Select Idea').first().json;
const openaiStatus = {
  idea_generation: ideaStatusNode.openai_status_ideas,
  product_creation: d.openai_status_product || 'not_run',
  final_revision: d.revision_status || (d.review_needs_revision ? 'skipped: AI-call budget does not allow a 4th call' : 'not_run'),
};
const aiCallsUsed = (ideaStatusNode.ai_calls_ideas || 0) + (d.ai_calls_product || 0) + (d.ai_calls_review || 0) + (d.ai_calls_revision || 0);

const qaPassed = failures.length === 0;
const productStatus = qaPassed ? 'pending_approval' : 'rejected_qa';
const keyBase = p && str(p.title) ? norm(p.title).split(' ').join('-').slice(0, 80) : 'no-product-' + $execution.id;
const productKey = 'lf-' + cfg.run_mode + '-' + keyBase;
const now = new Date().toISOString();
const allErrors = [].concat(sel.idea_errors || [], d.product_errors || [], d.review_errors || []);

return [{ json: {
  product: p,
  product_key: productKey,
  qa_passed: qaPassed,
  qa_failures: failures,
  qa_warnings: warnings,
  product_status: productStatus,
  approval_status: qaPassed ? 'pending_approval' : 'not_requested',
  openai_status: openaiStatus,
  claude_status: claudeStatus,
  review: d.review || null,
  ai_calls_used: aiCallsUsed,
  errors: allErrors,
  approval_payload: qaPassed ? {
    product_key: productKey,
    title: p.title,
    price: p.suggested_price_idr,
    currency: cfg.currency,
    score: sel.selected_score,
    qa_warnings: warnings,
    note: 'Approving marks the draft as approved only. Nothing is published automatically (auto_publish=false).',
  } : null,
  record: {
    product_key: productKey,
    product_title: p ? str(p.title) : '',
    run_mode: cfg.run_mode,
    product_status: productStatus,
    approval_status: qaPassed ? 'pending_approval' : 'not_requested',
    score: sel.selected_score || 0,
    score_breakdown_json: JSON.stringify(sel.selected_score_breakdown || {}),
    price_idr: p ? Number(p.suggested_price_idr) || 0 : 0,
    currency: cfg.currency,
    target_audience: p ? str(p.target_audience) : '',
    description: p ? str(p.description) : '',
    outline_json: JSON.stringify(p ? { outline: p.outline || [], deliverables: p.deliverables || [], customer_benefits: p.customer_benefits || [], product_content: p.product_content || null } : {}),
    sales_copy: JSON.stringify(p ? p.sales_copy || {} : {}),
    qa_passed: qaPassed,
    qa_results_json: JSON.stringify({ failures: failures, warnings: warnings }),
    openai_status: JSON.stringify(openaiStatus),
    claude_status: claudeStatus,
    review_feedback_json: JSON.stringify(d.review || null),
    approval_notes: '',
    errors_json: JSON.stringify(allErrors),
    execution_id: String($execution.id),
    last_updated: now,
  },
} }];

// Maps the owner's form submission to a status. No submission (72h timeout) keeps the draft pending_approval.
const qa = $('Quality Assurance').first().json;
const f = $input.first().json || {};
const decision = f['Decision'] || null;
const reviewer = String(f['Reviewer name'] || '').trim();
const notes = String(f['Notes'] || '').trim();
let approval = 'pending_approval';
let status = 'pending_approval';
if (decision === 'Approve draft') { approval = 'approved'; status = 'approved_not_published'; }
else if (decision === 'Request changes') { approval = 'changes_requested'; status = 'changes_requested'; }
else if (decision === 'Reject') { approval = 'rejected_by_owner'; status = 'rejected_by_owner'; }
const now = new Date().toISOString();
return [{ json: {
  product_key: qa.product_key,
  decision_submitted: !!decision,
  approval_decision: decision || 'none_timed_out',
  approval_status: approval,
  product_status: status,
  reviewer_name: decision ? reviewer : '',
  approval_notes: decision ? notes : 'No owner response within 72 hours; still pending_approval. Rerun to request approval again.',
  decided_at: decision ? now : '',
  last_updated: now,
} }];

// Single structured report for every path (invalid config, no candidate, QA failed, approval decided).
function getItem(name) { try { const n = $(name); if (n.isExecuted) return n.first(); } catch (e) {} return null; }
function get(name) { const item = getItem(name); return item ? item.json : null; }
function errMsg(e) { if (!e) return ''; if (typeof e === 'string') return e; return e.message || JSON.stringify(e); }
const v = get('Validate Configuration') || {};
const cfg = v.config || {};
const existing = get('Prepare Existing Records');
const dup = get('Detect Duplicates');
const sc = get('Score & Select Idea');
const qa = get('Quality Assurance');
const save = get('Save Product Record');
const appr = get('Record Approval Decision');
const upd = get('Update Approval Status');
const fileItem = getItem('Build Product Files');
const files = fileItem ? fileItem.json : null;

const errors = [].concat(v.config_errors || []);
if (existing && existing.load_error) errors.push('Data table load error: ' + existing.load_error);
if (qa) errors.push.apply(errors, qa.errors || []); else if (sc) errors.push.apply(errors, sc.idea_errors || []);

let persistence;
if (cfg.run_mode === 'simulation') persistence = 'skipped: safe simulation mode; no product rows were written';
else if (!save) persistence = 'not_persisted: run stopped before the persistence step';
else if (save.error) { persistence = 'failed: ' + errMsg(save.error); errors.push('Persistence failed: ' + errMsg(save.error)); }
else persistence = 'saved: Data Table lynkfusion_products (upsert by product_key ' + (qa ? qa.product_key : '') + ')';
if (upd) {
  if (upd.error) { persistence += '; approval update failed: ' + errMsg(upd.error); errors.push('Approval status update failed: ' + errMsg(upd.error)); }
  else persistence += '; approval decision saved';
}

let approvalStatus = 'not_requested';
if (appr) approvalStatus = appr.approval_status;
else if (qa) approvalStatus = qa.qa_passed ? 'pending_approval' : 'not_requested: QA failed';

const openai = qa ? qa.openai_status : { idea_generation: sc ? sc.openai_status_ideas : (dup ? dup.openai_status_ideas : 'not_run'), product_creation: 'not_run', final_revision: 'not_run' };
let claude = qa ? qa.claude_status : 'not_run: run stopped before review step';

let next;
if (!v.config_valid) next = 'Fix the configuration errors in the "Configuration" node and run again.';
else if (sc && !sc.has_valid_candidate) next = cfg.run_mode === 'live' ? 'No valid idea. Check Groq status (credential selected and "Groq Generate Ideas" connected), then review the exact provider error before any retry.' : 'No valid sample idea remained after duplicate checks; adjust sample data or switch to live mode.';
else if (qa && !qa.qa_passed) next = 'Fix the QA failures listed, then rerun. Nothing was sent for approval.';
else if (cfg.run_mode === 'simulation' && qa && qa.qa_passed) next = 'Simulation finished with no AI calls and no database write. Download the Markdown and HTML files from the Build Product Files node output. They are sample drafts, not ready for sale. When API costs/credentials are confirmed, switch run_mode to live for a maximum of 2 AI calls; Lynk publishing still requires manual upload because no product-creation node is configured.';
else if (cfg.run_mode === 'simulation' && qa) next = 'Simulation finished but QA failed. Review qa_results; no database write or approval wait occurred. No AI calls were made.';
else if (appr && appr.approval_status === 'approved') next = 'Draft approved. Publishing is NOT implemented in this workflow: upload the product file and enter the approved sales copy/price in Lynk dashboard manually.';
else if (appr && appr.approval_status === 'changes_requested') next = 'Owner requested changes: revise the draft using the notes and rerun.';
else if (appr && appr.approval_status === 'rejected_by_owner') next = 'Owner rejected the draft. Run again to pick a different idea.';
else next = 'Owner approval still pending (no decision within 72 hours). Rerun and open the approval_form_url stored in lynkfusion_products.';

const p = qa ? qa.product : null;
const resultItem = { json: {
  run_mode: cfg.run_mode || 'unknown',
  primary_ai: cfg.primary_ai || 'groq',
  ai_provider: 'Groq Chat Completions (OpenAI-compatible API)',
  config_valid: !!v.config_valid,
  config_warnings: v.config_warnings || [],
  ideas_generated: dup ? dup.ideas_generated : 0,
  duplicates_rejected: dup ? dup.duplicates_rejected : 0,
  close_matches_flagged: dup ? dup.close_matches_flagged : 0,
  existing_record_source: existing ? existing.record_source : 'not_loaded',
  duplicate_check_note: dup ? dup.duplicate_check_note : null,
  selected_idea: sc ? sc.selected_idea : null,
  score: sc ? sc.selected_score : null,
  score_breakdown: sc ? sc.selected_score_breakdown : null,
  scoring_method: sc ? sc.scoring_method : null,
  ranked_ideas: sc ? sc.ranked_ideas : [],
  proposed_price: p ? p.suggested_price_idr : null,
  currency: cfg.currency || 'IDR',
  product_outline: p ? { title: p.title, subtitle: p.subtitle, description: p.description, target_audience: p.target_audience, customer_benefits: p.customer_benefits, deliverables: p.deliverables, outline: p.outline, pricing_rationale: p.pricing_rationale, draft_label: p.draft_label } : null,
  product_content: p ? (p.product_content || null) : null,
  product_files_ready: !!(files && files.product_files_ready),
  product_file_names: files ? files.product_file_names : [],
  product_file_status: files ? files.product_file_status : 'not_created',
  sales_copy: p ? p.sales_copy : null,
  qa_results: qa ? { passed: qa.qa_passed, failures: qa.qa_failures, warnings: qa.qa_warnings } : null,
  openai_status: openai,
  claude_status: claude,
  claude_review: qa ? qa.review : null,
  ai_calls_used: qa ? qa.ai_calls_used : 0,
  ai_call_limit: cfg.max_ai_calls_per_execution,
  product_status: cfg.run_mode === 'simulation' ? 'simulation_draft_only' : (appr ? appr.product_status : (qa ? qa.product_status : 'not_created')),
  approval_status: cfg.run_mode === 'simulation' ? 'not_requested_simulation' : approvalStatus,
  approval_notes: appr ? appr.approval_notes : null,
  approval_decision: appr ? appr.approval_decision : null,
  reviewer_name: appr ? appr.reviewer_name : null,
  approval_form_url: (cfg.run_mode === 'live' && qa && qa.qa_passed) ? ($execution.resumeFormUrl || null) : null,
  persistence_status: persistence,
  published: false,
  disclaimer: 'Nothing was published. A successful execution is not evidence of market demand, validation, or sales.',
  errors: errors,
  next_required_action: next,
  finished_at: new Date().toISOString(),
} };
if (fileItem && fileItem.binary) resultItem.binary = fileItem.binary;
return [resultItem];

// SIMULATION ONLY: realistic sample product draft for the selected idea. No API calls.
const sel = $('Score & Select Idea').first().json.selected_idea;
const DRAFT = 'DRAFT (simulation sample) - not reviewed, not approved, not published';
const library = {
  sop: {
    title: 'Kit SOP Admin Online Shop: 25 Template Siap Pakai',
    subtitle: 'Standarkan cara admin membalas chat, memproses pesanan, dan menangani komplain',
    description: 'Kit berisi 25 dokumen SOP siap edit untuk online shop yang dijalankan bersama admin. Setiap SOP menjelaskan langkah kerja, contoh kalimat, dan titik pengecekan sehingga pemilik toko bisa menyerahkan tugas harian tanpa harus menjelaskan ulang setiap kali ada admin baru. Disusun untuk alur kerja Shopee, Tokopedia, TikTok Shop, dan WhatsApp.',
    customer_benefits: ['Admin baru punya panduan tertulis sejak hari pertama', 'Balasan chat pelanggan lebih konsisten antar admin', 'Checklist harian membantu mengurangi salah input dan salah kirim pesanan', 'Pemilik toko memiliki dokumen kerja yang bisa diperbarui sendiri'],
    deliverables: [
      { name: '25 template SOP', format: 'Notion dan Google Docs', details: 'Penerimaan pesanan, pengemasan, retur, komplain, stok, promo, serah terima shift, dan lainnya.' },
      { name: 'Bank 60 script balasan chat', format: 'Google Docs', details: 'Salam, konfirmasi pesanan, keterlambatan, stok habis, komplain, dan permintaan ulasan.' },
      { name: 'Checklist harian dan mingguan admin', format: 'Google Sheets', details: 'Daftar tugas yang dapat dicentang dan direkap oleh pemilik toko.' },
      { name: 'Panduan implementasi 7 hari', format: 'PDF', details: 'Urutan menerapkan SOP, cara melatih admin, dan cara merevisi SOP.' },
    ],
    outline: [
      { section: '1. Fondasi SOP toko', contents: ['Cara membaca dan mengedit template', 'Menentukan peran pemilik dan admin', 'Standar waktu balas chat'] },
      { section: '2. SOP pesanan', contents: ['Verifikasi pesanan masuk', 'Pengemasan dan foto bukti kemasan', 'Input resi dan update status'] },
      { section: '3. SOP layanan pelanggan', contents: ['Script balasan per situasi', 'Alur penanganan komplain', 'Alur retur dan refund sesuai kebijakan marketplace'] },
      { section: '4. SOP stok dan promo', contents: ['Cek stok harian', 'Persiapan kampanye tanggal kembar', 'Update harga dan voucher'] },
      { section: '5. Kontrol dan evaluasi', contents: ['Checklist harian admin', 'Rekap mingguan untuk pemilik', 'Cara merevisi SOP berdasarkan kendala nyata'] },
    ],
    suggested_price_idr: 79000,
    pricing_rationale: 'Berada di tengah rentang harga 19.000-149.000 IDR; mencakup 4 jenis file siap edit dan ditujukan untuk pemilik usaha yang menghemat waktu pelatihan admin. Harga perlu divalidasi dengan penjualan nyata.',
